INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Tablets für Präsentationen entscheidend?', 2, '[{"text": "Displaygröße", "correct": true, "because": "Wichtig für Sichtbarkeit"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Kein funktionaler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Tablet für komplexe Softwareentwicklung geeignet?', 1, '[{"text": "Nein", "correct": true, "because": "Begrenzte Leistung und Eingabemöglichkeiten"}, {"text": "Ja", "correct": false, "because": "Eher für einfache Aufgaben geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Tablets für den mobilen Einsatz attraktiv?', 5, '[{"text": "Geringes Gewicht", "correct": true, "because": "Erleichtert Transport"}, {"text": "Touchscreen", "correct": true, "because": "Intuitive Bedienung"}, {"text": "Anzahl der USB-Ports", "correct": false, "because": "Wenig relevant"}, {"text": "Akkulaufzeit", "correct": true, "because": "Wichtig für Mobilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Tablets richtig? a) Sie haben immer weniger Leistung als Notebooks. b) Sie sind für Spiele ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "High-End-Tablets können stark sein"}, {"text": "Beides stimmt", "correct": false, "because": "Tablets können Spiele gut nutzen"}, {"text": "Nur b) stimmt", "correct": false, "because": "Leistung ist oft ausreichend"}, {"text": "Beides falsch", "correct": true, "because": "Beides hängt von Modellen ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Tablets für den Schulunterricht ignorieren?', 2, '[{"text": "Prozessorleistung", "correct": false, "because": "Wichtig für Apps"}, {"text": "Design der Verpackung", "correct": true, "because": "Kein Einfluss auf Nutzung"}, {"text": "Speichergröße", "correct": false, "because": "Relevant für Daten"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Tablets für den Schulunterricht entscheidend?', 2, '[{"text": "Touchscreen-Funktionalität", "correct": true, "because": "Erleichtert interaktives Lernen"}, {"text": "Anzahl der USB-Anschlüsse", "correct": false, "because": "Weniger wichtig für Tablets"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Tablet immer weniger leistungsstark als ein Notebook?', 1, '[{"text": "Nein", "correct": true, "because": "High-End-Tablets können Notebooks annähern"}, {"text": "Ja", "correct": false, "because": "Leistung variiert je nach Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Tablets für den mobilen Einsatz geeignet?', 5, '[{"text": "Geringes Gewicht", "correct": true, "because": "Erleichtert Transport"}, {"text": "Lange Akkulaufzeit", "correct": true, "because": "Ermöglicht längeren Einsatz"}, {"text": "Große Festplattenkapazität", "correct": false, "because": "Tablets nutzen meist Flash-Speicher"}, {"text": "Portabilität", "correct": true, "because": "Kompakte Bauweise"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Tablets richtig? a) Sie eignen sich gut für Videobearbeitung. b) Sie sind immer günstiger als Notebooks.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Videobearbeitung ist begrenzt"}, {"text": "Nur b) stimmt", "correct": false, "because": "Preise variieren stark"}, {"text": "Beides stimmt", "correct": false, "because": "Beides ist nicht generell wahr"}, {"text": "Beides falsch", "correct": true, "because": "Beides hängt vom Modell ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Tablets für Spiele ignorieren?', 2, '[{"text": "Displayauflösung", "correct": false, "because": "Wichtig für Grafikqualität"}, {"text": "Gehäusefarbe", "correct": true, "because": "Hat keinen Einfluss auf Leistung"}, {"text": "Prozessorleistung", "correct": false, "because": "Entscheidend für Spiele"}]');
